updated AS (
  UPDATE gs_entities e
     SET lga_name = t.lga_name, lga_code = t.lga_code, lga_source = t.stamp
    FROM targets t
   WHERE e.gs_id = t.gs_id
     AND e.lga_name IS NOT DISTINCT FROM NULLIF(t.guard, '')
  RETURNING e.gs_id, t.lga_name, t.stamp
)
SELECT stamp, lga_name AS council, count(*) AS rows
  FROM updated GROUP BY 1, 2 ORDER BY 1, 3 DESC;

