SELECT t.gs_id, e.canonical_name, COALESCE(e.lga_name,'(unplaced)') AS current_lga
  FROM targets t
  JOIN gs_entities e ON e.gs_id = t.gs_id
 WHERE e.lga_source IS DISTINCT FROM t.stamp OR e.lga_name IS DISTINCT FROM t.lga_name;
